S.append(S2(c,B+' · 3','Cài đặt hàng đợi: list chậm, deque nhanh',card('Chi phí các thao tác',T(tr('','list','deque',h=True)+tr('thêm cuối','append O(1)','append O(1)')+tr('lấy đầu','<b>pop(0): O(n)</b>','<b>popleft(): O(1)</b>')+tr('thêm đầu','insert(0, x): O(n)','appendleft(x): O(1)'))+WARN('Dùng <code>pop(0)</code> trong vòng lặp lớn khiến thuật toán <b>O(n²)</b>.')),CODE('from collections import deque\nq = deque()\nq.append(1)\nq.append(2)\nq.append(3)\nprint(q, q[0])\nprint(q.popleft(), q)\nq.appendleft(9)\nprint(q, len(q))',22)+R('from collections import deque\nq = deque()\nq.append(1)\nq.append(2)\nq.append(3)\nprint(q, q[0])\nprint(q.popleft(), q)\nq.appendleft(9)\nprint(q, len(q))','',22,'Kết quả')))
S.append(S2(c,B+' · 3','Chạy tay: xoay vòng rồi bỏ đầu',card('Bài trong đề',P('q = [1, 2, 3, 4, 5]. Lặp: đưa phần tử đầu vào <b>out</b>, rồi chuyển phần tử đầu mới xuống <b>cuối</b> hàng đợi. Dừng khi còn 1 phần tử.','Theo dõi từng vòng: <b>(1) out=[1], q=[3,4,5,2]; (2) out=[1,3], q=[5,2,4]; (3) out=[1,3,5], q=[4,2]; (4) out=[1,3,5,4], q=[2]</b>.')),CODE('q = [1, 2, 3, 4, 5]\nout = []\nwhile len(q) > 1:\n    out.append(q.pop(0))\n    q.append(q.pop(0))\nprint(out, q)',22)+R('q = [1, 2, 3, 4, 5]\nout = []\nwhile len(q) > 1:\n    out.append(q.pop(0))\n    q.append(q.pop(0))\nprint(out, q)','',26,'Kết quả')))
S.append(S2(c,B+' · 3','Bài Josephus: bỏ qua hai, loại người thứ ba',card('Đề bài',P('7 bạn đánh số 1..7 xếp vòng tròn. Lần lượt <b>bỏ qua hai bạn</b>, rồi <b>loại bạn thứ ba</b>; cứ thế đến khi còn một bạn. Ai còn lại?','Mô phỏng bằng <b>deque</b>: hai lần “đưa đầu xuống cuối”, rồi <b>popleft</b> (loại).')),CODE('from collections import deque\nq = deque(range(1, 8))\nloai = []\nwhile len(q) > 1:\n    for _ in range(2):\n        q.append(q.popleft())\n    loai.append(q.popleft())\nprint(loai, q[0])',21)+R('from collections import deque\nq = deque(range(1, 8))\nloai = []\nwhile len(q) > 1:\n    for _ in range(2):\n        q.append(q.popleft())\n    loai.append(q.popleft())\nprint(loai, q[0])','',24,'Thứ tự bị loại và người còn lại')+KEY('Thứ tự loại: 3, 6, 2, 7, 5, 1 → còn lại <b>4</b>.')))
S.append(S2(c,B+' · 3','Mô phỏng phục vụ khách hàng',card('Ứng dụng thực tế',P('Khách đến lúc t, phục vụ mất d phút, <b>theo thứ tự đến</b> (FIFO).','Tính <b>thời gian chờ</b> mỗi khách: thời điểm bắt đầu phục vụ − thời điểm đến.')),CODE('from collections import deque\nden = deque([(0, 5), (2, 3), (4, 2), (10, 1)])\nt = 0\nwait = []\nwhile den:\n    a, d = den.popleft()\n    t = max(t, a)\n    wait.append(t - a)\n    t += d\nprint(wait, sum(wait) / len(wait))',21)+R('from collections import deque\nden = deque([(0, 5), (2, 3), (4, 2), (10, 1)])\nt = 0\nwait = []\nwhile den:\n    a, d = den.popleft()\n    t = max(t, a)\n    wait.append(t - a)\n    t += d\nprint(wait, sum(wait) / len(wait))','',24,'Kết quả')))
