S.append(S2(c,B+' · 4','BFS: loang theo từng lớp bằng hàng đợi',card('Ý tưởng',P('<b>Duyệt theo chiều rộng</b>: xét đỉnh gần nguồn trước, rồi các đỉnh xa hơn một bước, hai bước…','Dùng <b>hàng đợi</b>: lấy đầu, thêm các láng giềng <b>chưa thăm</b> vào cuối.','Nhờ vậy BFS tìm <b>đường đi ngắn nhất</b> (số cạnh) trong đồ thị <b>không trọng số</b>.')),CODE('from collections import deque\nke = {1: [2, 3], 2: [4], 3: [4, 5], 4: [6], 5: [6], 6: []}\nd = {1: 0}\nq = deque([1])\nwhile q:\n    u = q.popleft()\n    for v in ke[u]:\n        if v not in d:\n            d[v] = d[u] + 1\n            q.append(v)\nprint(d)',20)+R('from collections import deque\nke = {1: [2, 3], 2: [4], 3: [4, 5], 4: [6], 5: [6], 6: []}\nd = {1: 0}\nq = deque([1])\nwhile q:\n    u = q.popleft()\n    for v in ke[u]:\n        if v not in d:\n            d[v] = d[u] + 1\n            q.append(v)\nprint(d)','',24,'Khoảng cách từ đỉnh 1')+KEY('Đỉnh 6 cách đỉnh 1 <b>3 bước</b> (1→2→4→6).')))
S.append(S2(c,B+' · 4','BFS trên mê cung: đường đi ngắn nhất',card('Lưới 0/1',P('Ô 0 đi được, ô 1 là tường. Từ (0,0) đến (n−1, m−1), mỗi bước sang ô kề (4 hướng).','<code>d[i][j]</code> = số bước nhỏ nhất đến ô (i, j); −1 nếu chưa đến.')),CODE('from collections import deque\ng = ["0010", "0110", "0000", "1110", "0000"]\nn, m = 5, 4\nd = [[-1] * m for _ in range(n)]\nd[0][0] = 0\nq = deque([(0, 0)])\nwhile q:\n    x, y = q.popleft()\n    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):\n        u, v = x + dx, y + dy\n        if 0 <= u < n and 0 <= v < m and g[u][v] == "0" and d[u][v] < 0:\n            d[u][v] = d[x][y] + 1\n            q.append((u, v))\nprint(d[n-1][m-1])',16)+R('from collections import deque\ng = ["0010", "0110", "0000", "1110", "0000"]\nn, m = 5, 4\nd = [[-1] * m for _ in range(n)]\nd[0][0] = 0\nq = deque([(0, 0)])\nwhile q:\n    x, y = q.popleft()\n    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):\n        u, v = x + dx, y + dy\n        if 0 <= u < n and 0 <= v < m and g[u][v] == "0" and d[u][v] < 0:\n            d[u][v] = d[x][y] + 1\n            q.append((u, v))\nprint(d[n-1][m-1])','',24,'Số bước ngắn nhất')))
S.append(S2(c,B+' · 4','Ngăn xếp đơn điệu: phần tử lớn hơn kế tiếp',card('Bài toán',P('Với mỗi a[i], tìm phần tử <b>đầu tiên bên phải lớn hơn</b> nó (hoặc −1).','<b>Cách ngây thơ</b>: O(n²). <b>Ngăn xếp đơn điệu</b>: O(n) — mỗi phần tử vào và ra ngăn xếp <b>đúng một lần</b>.','Ngăn xếp lưu <b>chỉ số</b> các phần tử chưa tìm được kết quả (giá trị giảm dần).')),CODE('a = [2, 1, 5, 3, 6, 4]\nkq = [-1] * len(a)\nst = []\nfor i, x in enumerate(a):\n    while st and a[st[-1]] < x:\n        kq[st.pop()] = x\n    st.append(i)\nprint(kq)',22)+R('a = [2, 1, 5, 3, 6, 4]\nkq = [-1] * len(a)\nst = []\nfor i, x in enumerate(a):\n    while st and a[st[-1]] < x:\n        kq[st.pop()] = x\n    st.append(i)\nprint(kq)','',24,'Kết quả')+KEY('Vòng while lồng trong for nhưng tổng số lần pop ≤ n → <b>O(n)</b>.')))
S.append(TB(c,B+' · 4','Theo dõi ngăn xếp đơn điệu a = [2, 1, 5, 3, 6, 4]',['i','x','pop (gán kq)','ngăn xếp (chỉ số) sau'],[['0','2','—','[0]'],['1','1','—','[0, 1]'],['2','5','pop 1 (kq=5), pop 0 (kq=5)','[2]'],['3','3','—','[2, 3]'],['4','6','pop 3 (kq=6), pop 2 (kq=6)','[4]'],['5','4','—','[4, 5]']],note=KEY('Còn lại chỉ số 4, 5 trong ngăn xếp: kq = <b>−1</b>. Kết quả [5, 5, 6, 6, −1, −1].')))
S.append(S2(c,B+' · 4','Hàng đợi hai đầu: cửa sổ trượt lớn nhất',card('Bài toán “max trong mọi đoạn k”',P('Dãy a, với mỗi cửa sổ k phần tử liên tiếp, in <b>giá trị lớn nhất</b>.','Dùng <b>deque</b> lưu chỉ số, giữ giá trị <b>giảm dần</b>: bỏ cuối nếu nhỏ hơn x; bỏ đầu nếu ra khỏi cửa sổ.','Tổng thời gian <b>O(n)</b>.')),CODE('from collections import deque\na = [1, 3, -1, -3, 5, 3, 6, 7]\nk = 3\ndq = deque()\nkq = []\nfor i, x in enumerate(a):\n    while dq and a[dq[-1]] <= x:\n        dq.pop()\n    dq.append(i)\n    if dq[0] <= i - k:\n        dq.popleft()\n    if i >= k - 1:\n        kq.append(a[dq[0]])\nprint(kq)',19)+R('from collections import deque\na = [1, 3, -1, -3, 5, 3, 6, 7]\nk = 3\ndq = deque()\nkq = []\nfor i, x in enumerate(a):\n    while dq and a[dq[-1]] <= x:\n        dq.pop()\n    dq.append(i)\n    if dq[0] <= i - k:\n        dq.popleft()\n    if i >= k - 1:\n        kq.append(a[dq[0]])\nprint(kq)','',24,'Kết quả')))
S.append(S2(c,B+' · 5','Hàng đợi ưu tiên (heapq)',card('Lấy phần tử nhỏ nhất ra trước',P('<b>Hàng đợi ưu tiên</b>: <b>push</b> bất kì, <b>pop</b> luôn lấy phần tử <b>nhỏ nhất</b>.','Cài đặt bằng <b>đống nhị phân</b> (heapq): push và pop đều <b>O(log n)</b>.','Muốn lấy <b>lớn nhất</b>: đẩy giá trị <b>âm</b>.')),CODE('import heapq\nh = []\nfor x in [5, 2, 8, 1, 9]:\n    heapq.heappush(h, x)\nprint([heapq.heappop(h) for _ in range(3)])\nh2 = [-x for x in [5, 2, 8]]\nheapq.heapify(h2)\nprint(-heapq.heappop(h2))',21)+R('import heapq\nh = []\nfor x in [5, 2, 8, 1, 9]:\n    heapq.heappush(h, x)\nprint([heapq.heappop(h) for _ in range(3)])\nh2 = [-x for x in [5, 2, 8]]\nheapq.heapify(h2)\nprint(-heapq.heappop(h2))','',24,'Kết quả')+KEY('Ứng dụng: <b>Dijkstra</b>, ghép k danh sách, lấy k lớn nhất.')))
S.append(TB(c,B+' · 5','So sánh các cấu trúc',['','Ngăn xếp','Hàng đợi','Hàng đợi ưu tiên'],[['Nguyên tắc','LIFO','FIFO','nhỏ nhất (hoặc lớn nhất) trước'],['Python','list append/pop','deque append/popleft','heapq'],['Thao tác lấy','O(1)','O(1) (deque)','O(log n)'],['Ứng dụng','ngoặc, hậu tố, DFS, hoàn tác','BFS, mô phỏng hàng đợi','Dijkstra, lập lịch']],note=KEY('Nhớ: <b>DFS ↔ ngăn xếp</b>, <b>BFS ↔ hàng đợi</b>. Đổi cấu trúc là đổi thứ tự duyệt.')))
S.append(SELF(c,B+' · 6','Tự kiểm tra: ngăn xếp tạm','Chương trình in ra gì? Theo dõi st.','st = []\nkq = []\nfor ch in "abcdef":\n    st.append(ch)\n    if len(st) == 3:\n        kq.append(st.pop())\n        kq.append(st.pop())\nprint("".join(kq), "".join(st))',P('a, b → st = [a, b]; c → [a, b, c] (đủ 3) → pop c, pop b → kq = “cb”, st = [a].','d → [a, d]; e → [a, d, e] → pop e, pop d → kq = “cbed”, st = [a].','f → [a, f]. Kết quả: <b>“cbed”</b> và <b>“af”</b>.')+R('st = []\nkq = []\nfor ch in "abcdef":\n    st.append(ch)\n    if len(st) == 3:\n        kq.append(st.pop())\n        kq.append(st.pop())\nprint("".join(kq), "".join(st))','',24,'Kết quả thật'),21))
S.append(SELF(c,B+' · 6','Tự kiểm tra: Josephus','7 bạn, bỏ qua hai, loại bạn thứ ba. Ai còn lại cuối cùng?','from collections import deque\nq = deque(range(1, 8))\nwhile len(q) > 1:\n    for _ in range(2):\n        q.append(q.popleft())\n    q.popleft()\nprint(q[0])',P('q = [1..7]. Vòng 1: xoay 1, 2 → [3,4,5,6,7,1,2]; loại 3 → [4,5,6,7,1,2].','Vòng 2: xoay 4, 5; loại 6 → [7,1,2,4,5]. Vòng 3: xoay 7, 1; loại 2 → [4,5,7,1].','Vòng 4: xoay 4, 5; loại 7 → [1,4,5]. Vòng 5: xoay 1, 4; loại 5 → [1,4]. Vòng 6: xoay 1, 4 → [1,4] (hai lần xoay về nguyên); loại 1 → [4].','Người còn lại: <b>4</b>.')+R('from collections import deque\nq = deque(range(1, 8))\nwhile len(q) > 1:\n    for _ in range(2):\n        q.append(q.popleft())\n    q.popleft()\nprint(q[0])','',24,'Kết quả thật'),19))
S.append(SELF(c,B+' · 6','Tự kiểm tra (HSG): kiểm tra ngoặc','Hàm can_bang có đúng không với xâu “())”? Và với “((” ? Hãy chỉ ra hai lỗi nếu thiếu hai điều kiện nhất định.',CB+'\nprint(can_bang("())"), can_bang("(("))',P('<b>“())”</b>: push (, pop → rỗng, gặp ) nữa: <b>st rỗng</b> nên <code>not st</code> đúng → trả <b>False</b>. Nếu thiếu <code>not st or</code> thì <code>st.pop()</code> gây <b>IndexError</b>.','<b>“((”</b>: hết xâu mà st còn 2 phần tử → <code>return not st</code> = <b>False</b>. Nếu cuối hàm chỉ <code>return True</code> thì <b>sai</b>.')+R(CB+'\nprint(can_bang("())"), can_bang("(("), can_bang("([{}])"))','',22,'Kết quả thật'),18))
S+=END(c,B,['<b>Ngăn xếp LIFO</b>: append/pop ở cuối list; luôn kiểm tra rỗng trước khi pop.','<b>Hàng đợi FIFO</b>: dùng <b>deque</b> (popleft O(1)); <code>pop(0)</code> của list là O(n).','Ngoặc cân bằng; hậu tố (pop b rồi a); Josephus bằng deque.','<b>BFS</b> = hàng đợi, đường đi ngắn nhất không trọng số; DFS = ngăn xếp/đệ quy.','<b>Ngăn xếp đơn điệu</b> và <b>deque cửa sổ trượt</b> đưa O(n²) về O(n).','<b>heapq</b>: hàng đợi ưu tiên O(log n).'],[('Đỉnh ngăn xếp','st[-1]'),('Lấy đầu hàng đợi','popleft()'),('BFS','deque'),('Hậu tố','pop b, rồi a')],'Pop khi rỗng; quên kiểm tra rỗng cuối; dùng list.pop(0) trong vòng lặp lớn.',['Đếm ngoặc <b>không đủ</b>: phải đúng thứ tự lồng.','Hậu tố: <b>a op b</b> với b pop trước.','Mỗi phần tử vào/ra ngăn xếp đơn điệu một lần → O(n).','BFS đánh dấu thăm <b>khi đẩy vào hàng đợi</b>.'],['<b>Dijkstra</b> với heapq.','<b>Topo sort</b> (Kahn) bằng hàng đợi.','<b>Hàng đợi vòng</b> (circular buffer).'],
 [('Ngăn xếp: vào sau ra trước hay vào trước ra trước?',),('Cách lấy phần tử đầu của deque?',),('Cấu trúc dùng cho BFS?',),('<code>[].pop()</code> gây lỗi gì?',),('Độ phức tạp của <code>pop(0)</code> trên list?',)],
 [('<b>Vào sau, ra trước</b> (LIFO).',),('<b>popleft()</b>.',),('<b>Hàng đợi</b> (deque).',),('<b>IndexError</b>.',),('<b>O(n)</b>.',)],
 [('Mức 1. Đảo ngược một dãy số bằng ngăn xếp. Thử [1, 2, 3, 4].',),('Mức 1. Kiểm tra xâu chỉ có ( và ) có cân bằng không. Thử “(())”, “)(”.',),('Mức 2. Tính giá trị biểu thức hậu tố “3 4 + 2 *”.',),('Mức 2. Mô phỏng hàng đợi: lệnh “push x”, “pop”, “size”.',),('Mức 3 (HSG). Với dãy a, tìm với mỗi i phần tử <b>nhỏ hơn gần nhất bên trái</b> (hoặc −1) trong O(n).',),('Mức 3 (HSG). Mê cung n × m: đường đi ngắn nhất từ S đến E, in cả đường đi (lưu cha).',)],
 [(V('st=[1,2,3,4]\nr=[]\nwhile st: r.append(st.pop())\nprint(r)')+'.',),('Đếm cân bằng: ngăn xếp hoặc biến <code>d</code> (d &lt; 0 → sai) → '+V('def f(s):\n    d=0\n    for c in s:\n        d+=1 if c=="(" else -1\n        if d<0: return False\n    return d==0\nprint(f("(())"),f(")("))')+'.',),(V('st=[]\nfor t in "3 4 + 2 *".split():\n    if t in "+*":\n        b=st.pop();a=st.pop();st.append(a+b if t=="+" else a*b)\n    else: st.append(int(t))\nprint(st[-1])')+' (= (3 + 4) × 2).',),('Đọc lệnh, <code>q.append</code>, <code>q.popleft()</code>, <code>len(q)</code> (dùng deque).',),('Đổi chiều so sánh và duyệt trái → phải với ngăn xếp tăng dần → '+V('a=[3,1,4,1,5,9,2]\nkq=[-1]*len(a);st=[]\nfor i,x in enumerate(a):\n    while st and a[st[-1]]>=x: st.pop()\n    kq[i]=a[st[-1]] if st else -1\n    st.append(i)\nprint(kq)')+'.',),('BFS + mảng <code>cha[(x,y)]</code>; truy ngược từ E về S rồi đảo lại.',)],hper=2)
